CREATE TABLE IF NOT EXISTS paises (id SERIAL PRIMARY KEY, nome VARCHAR(100) UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS estados (id SERIAL PRIMARY KEY, pais_id INT REFERENCES paises(id), nome VARCHAR(100) NOT NULL, sigla CHAR(2) UNIQUE NOT NULL); CREATE TABLE IF NOT EXISTS cidades (id SERIAL PRIMARY KEY, estado_id INT REFERENCES estados(id), nome VARCHAR(100) NOT NULL, ativo BOOLEAN DEFAULT FALSE); CREATE TABLE IF NOT EXISTS bairros (id SERIAL PRIMARY KEY, cidade_id INT REFERENCES cidades(id), nome VARCHAR(100) NOT NULL);
